input.command:
$d = Get-Content "mi-sistema/clase-07/CLASE 07.excalidraw" -Raw | ConvertFrom-Json
$els = $d.elements
Write-Output "type: $($d.type) | version: $($d.version)"
Write-Output "total elements: $($els.Count)"
$ids = $els | ForEach-Object { $_.id }
Write-Output "unique ids: $(($ids.Count) -eq (($ids | Select-Object -Unique).Count))"
$rects = $els | Where-Object { $_.type -eq 'rectangle' }
Write-Output "rectangles: $($rects.Count)"
foreach ($r in $rects) {
  $lbl = $els | Where-Object { $_.containerId -eq $r.id }
  $boundOk = ($r.boundElements | Where-Object { $_.id -eq $lbl.id }).Count -gt 0
  $first = ($lbl.text -split "`n")[0]
  Write-Output "  $first -> $($r.width) x $($r.height) | bound ok: $boundOk | containerId ok: $($lbl.containerId -eq $r.id)"
}
$maxx = ($els | ForEach-Object { $_.x + $_.width } | Measure-Object -Maximum).Maximum
Write-Output "approx canvas width: $maxx"
